    68	    __asm__ volatile(
    69	        /* Load syscall number into $v0 */
    70	        "move $v0, %1\n\t"
    71	        
    72	        /* Load first four arguments into $a0-$a3 */
    73	        "move $a0, %2\n\t"
    74	        "move $a1, %3\n\t"
    75	        "move $a2, %4\n\t"
    76	        "move $a3, %5\n\t"
