  1278	int strncmp(const char* s1, const char* s2, size_t n) {
  1279	    // Early return if no characters to compare
  1280	    if (n == 0) {
  1281	        return 0;
  1282	    }
  1283	    
  1284	    // Compare at most n characters
  1285	    while (n > 0) {
  1286	        // If characters differ or we hit the end of either string
  1287	        if (*s1 != *s2 || *s1 == '\0') {
  1288	            return *(const unsigned char*)s1 - *(const unsigned char*)s2;
  1289	        }
  1290	        s1++;
  1291	        s2++;
  1292	        n--;
  1293	    }
  1294	    
  1295	    // If we compared exactly n characters with no differences
  1296	    return 0;
  1297	}
