  1360	    if (d < s || d >= s + n) {
  1361	        // Copy forwards (non-overlapping or d before s)
  1362	        return memcpy(dest, src, n);
  1363	    } else {
  1364	        // Copy backwards to handle overlapping regions
  1365	        for (size_t i = n; i > 0; i--) {
