  1472	    size_t count = 0;
  1473	    
  1474	    while (*str) {
  1475	        if (strchr(reject, *str) != NULL) {
  1476	            return count;
  1477	        }
  1478	        str++;
  1479	        count++;
  1480	    }
  1481	    
  1482	    return count;
  1483	}
