2832	            while (*str == ' ' || *str == '\t') str++;
2833	        } else {
2834	            /* Match literal character */
2835	            if (*format == *str) {
2836	                format++;
2837	                str++;
2838	            } else {
2839	                goto end;
2840	            }
2841	        }
2842	    }
2843	    
2844	end:
2845	    va_end(args);
2846	    return matched;
2847	}
