2867	/* Update puts to use direct syscall for stdout */
2868	int puts(const char* s) {
2869	    /* Calculate string length */
2870	    size_t len = 0;
2871	    const char* p = s;
2872	    while (*p) {
2873	        len++;
2874	        p++;
2875	    }
2876	    
2877	    /* For storing syscall results */
2878	    long result;
2879	    
2880	    /* Write the string directly to stdout */
2881	    if (len > 0) {
2882	      syscall6(SYS_write, 1, s, len, 0, 0, 0);
2883	        
2884	        /* We ignore errors for simplicity */
2885	    }
2886	    
2887	    /* Write the newline character */
2888	    char nl = '\n';
2889	    syscall6(SYS_write, 1, &nl, len, 0, 0, 0);
2890	    
2891	    return 1;
2892	}
