193	static char *GetRegistryString(registry_value_t *reg_val)
194	{
195	    HKEY key;
196	    DWORD len;
197	    DWORD valtype;
198	    char *result;
199	
200	    // Open the key (directory where the value is stored)
201	
202	    if (RegOpenKeyEx(reg_val->root, reg_val->path,
203	                     0, KEY_READ, &key) != ERROR_SUCCESS)
204	    {
205	        return NULL;
206	    }
207	
208	    result = NULL;
209	
210	    // Find the type and length of the string, and only accept strings.
211	
212	    if (RegQueryValueEx(key, reg_val->value,
213	                        NULL, &valtype, NULL, &len) == ERROR_SUCCESS
214	     && valtype == REG_SZ)
215	    {
216	        // Allocate a buffer for the value and read the value
217	
218	        result = malloc(len);
219	
220	        if (RegQueryValueEx(key, reg_val->value, NULL, &valtype,
221	                            (unsigned char *) result, &len) != ERROR_SUCCESS)
222	        {
223	            free(result);
224	            result = NULL;
225	        }
226	    }
227	
228	    // Close the key
229	
230	    RegCloseKey(key);
231	
232	    return result;
233	}
