235	// Check for the uninstall strings from the CD versions
236	
237	static void CheckUninstallStrings(void)
238	{
239	    unsigned int i;
240	
241	    for (i=0; i<arrlen(uninstall_values); ++i)
242	    {
243	        char *val;
244	        char *path;
245	        char *unstr;
246	
247	        val = GetRegistryString(&uninstall_values[i]);
248	
249	        if (val == NULL)
250	        {
251	            continue;
252	        }
253	
254	        unstr = strstr(val, UNINSTALLER_STRING);
255	
256	        if (unstr == NULL)
257	        {
258	            free(val);
259	        }
260	        else
261	        {
262	            path = unstr + strlen(UNINSTALLER_STRING);
263	
264	            AddIWADDir(path);
265	        }
266	    }
267	}
