389	// Returns true if the specified path is a path to a file
390	// of the specified name.
391	
392	static boolean DirIsFile(char *path, char *filename)
393	{
394	    size_t path_len;
395	    size_t filename_len;
396	
397	    path_len = strlen(path);
398	    filename_len = strlen(filename);
399	
400	    return path_len >= filename_len + 1
401	        && path[path_len - filename_len - 1] == DIR_SEPARATOR
402	        && !strcasecmp(&path[path_len - filename_len], filename);
403	}
