473	// When given an IWAD with the '-iwad' parameter,
474	// attempt to identify it by its name.
475	
476	static GameMission_t IdentifyIWADByName(char *name, int mask)
477	{
478	    size_t i;
479	    GameMission_t mission;
480	    char *p;
481	
482	    p = strrchr(name, DIR_SEPARATOR);
483	
484	    if (p != NULL)
485	    {
486	        name = p + 1;
487	    }
488	
489	    mission = none;
490	
491	    for (i=0; i<arrlen(iwads); ++i)
492	    {
493	        // Check if the filename is this IWAD name.
494	
495	        // Only use supported missions:
496	
497	        if (((1 << iwads[i].mission) & mask) == 0)
498	            continue;
499	
500	        // Check if it ends in this IWAD name.
501	
502	        if (!strcasecmp(name, iwads[i].name))
503	        {
504	            mission = iwads[i].mission;
505	            break;
506	        }
507	    }
508	
